{
  "$schema": "https://pets.studio/config.json",
  "name": "@openpets/telegram-bot",
  "version": "1.0.0",
  "title": "Telegram Bot",
  "subtitle": "Control Telegram bots via the Bot API",
  "description": "Send messages, manage chats, handle updates and interact with users through Telegram Bot API. Supports webhooks, inline keyboards, and all bot features.",
  "categories": [
    "telegram",
    "messaging",
    "communication",
    "bot"
  ],
  "main": "index.ts",
  "types": "index.ts",
  "keywords": [
    "opencode",
    "openpets",
    "plugin",
    "telegram",
    "bot",
    "messaging",
    "webhook"
  ],
  "openapiSpec": {
    "url": "https://raw.githubusercontent.com/alserom/telegram-bot-api-spec/main/openapi.json",
    "baseUrl": "https://api.telegram.org",
    "authType": "custom",
    "authEnvVar": "TELEGRAM_BOT_TOKEN",
    "responseFormat": "toon"
  },
  "envVariables": {
    "required": [
      {
        "name": "TELEGRAM_BOT_TOKEN",
        "description": "Bot token from BotFather (format: 123456:ABC-DEF1234ghIkl-zyx57W2v1u123ew11)",
        "provider": "Telegram",
        "priority": 1
      }
    ],
    "optional": []
  },
  "queries": [
    "test telegram bot connection",
    "send telegram message to user",
    "get telegram bot info",
    "set telegram webhook",
    "list telegram updates",
    "send telegram photo",
    "create telegram poll"
  ],
  "scenarios": {
    "basic-test": [
      "test telegram bot connection",
      "get bot information"
    ],
    "send-message": [
      "test telegram bot connection",
      "send message to chat"
    ]
  },
  "faq": [
    {
      "question": "How do I get a bot token?",
      "answer": "Message @BotFather on Telegram, create a new bot with /newbot, and copy the token provided. It looks like: 123456:ABC-DEF1234ghIkl-zyx57W2v1u123ew11"
    },
    {
      "question": "What's the difference between Telegram Bot and Telegram (User API)?",
      "answer": "Telegram Bot uses the HTTP Bot API with bot tokens - you control a bot account with limited permissions. Telegram (User API) uses MTProto and lets you access Telegram as your personal account with full access."
    },
    {
      "question": "Can I receive messages with this pet?",
      "answer": "Yes! Use getUpdates to poll for messages, or set up a webhook to receive real-time updates. The bot must be added to chats or users must start a conversation with it first."
    },
    {
      "question": "What can a bot do?",
      "answer": "Bots can send messages, photos, documents, polls, inline keyboards, handle commands, manage groups (if admin), and much more. See the Telegram Bot API documentation for full capabilities."
    }
  ],
  "scripts": {
    "build": "pets build",
    "quickstart": "opencode run \"test telegram bot connection\"",
    "test:connection": "opencode run \"test telegram bot connection\" --print-logs",
    "generate-openapi": "pets generate-openapi --verbose"
  },
  "dependencies": {
    "openpets-sdk": "^1.1.0",
    "dotenv": "^16.0.0"
  },
  "publishConfig": {
    "access": "public"
  },
  "files": [
    "index.ts",
    "index.js",
    "client.ts",
    "client.js",
    "*.d.ts",
    "lib/**/*",
    "src/**/*",
    "commands.json",
    "public/**/*",
    "prompts/**/*",
    "README.md"
  ]
}
